export interface GetTeamScheduleQuery {
  /** Season (calendar year). Default: the newest cached season. */
  season?: number;
}

/** Query parameters for {@link DynastyAPI.listStandings}. */
export interface ListStandingsQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
}

/** Query parameters for {@link DynastyAPI.listTeamStats}. */
export interface ListTeamStatsQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
}

/** Query parameters for {@link DynastyAPI.listMembers}. */
export interface ListMembersQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
}

/** Query parameters for {@link DynastyAPI.listPlayerStats}. */
export interface ListPlayerStatsQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
  /** Team key */
  team?: number;
}

/** Query parameters for {@link DynastyAPI.listAwards}. */
export interface ListAwardsQuery {
  /** Season. Default: newest with awards */
  season?: number;
  /** Week index */
  week?: number;
}

/** Query parameters for {@link DynastyAPI.listRecruits}. */
export interface ListRecruitsQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
  /** `recruits` (high school and JUCO), `transfers` (the transfer portal) or `overall` (both). Default: `recruits`. Transfer portal ranks are their own ranking and also start at 1. */
  type?: ListRecruitsType;
  /** Comma-separated star ratings, e.g. `4,5` */
  stars?: string;
  /** Position, e.g. `QB`, `ATH` */
  position?: string;
  /** Home state, e.g. `TX` */
  state?: string;
  /** `true`: committed or signed; `false`: neither */
  committed?: boolean;
  /** Committed or signed school, by team id (`team_id` in /team-stats) */
  school?: number;
}

/** Query parameters for {@link DynastyAPI.listRecruitCommits}. */
export interface ListRecruitCommitsQuery {
  /** `recruits` (high school and JUCO), `transfers` (the transfer portal) or `overall` (both). Default: `recruits`. Transfer portal ranks are their own ranking and also start at 1. */
  type?: ListRecruitCommitsType;
  /** Season. Default: newest with commitment changes */
  season?: number;
  /** Comma-separated star ratings, e.g. `4,5` */
  stars?: string;
  /** `commit`, `decommit` or `sign` */
  kind?: ListRecruitCommitsKind;
  /** Committed or signed school, by team id (`team_id` in /team-stats) */
  school?: number;
}

/** Query parameters for {@link DynastyAPI.listRecruitingClasses}. */
export interface ListRecruitingClassesQuery {
  /** Class type. Default: `overall` */
  type?: ListRecruitingClassesType;
  /** Conference name, e.g. `SEC` (case-insensitive) */
  conference?: string;
  /** Team key */
  team?: number;
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
}

/** Query parameters for {@link DynastyAPI.listRosters}. */
export interface ListRostersQuery {
  /** Season. Default: the newest cached season */
  season?: number;
  /** Team key. A CPU team's roster needs a paid plan (without one, only user teams match) */
  team?: number;
  /** Position, e.g. `QB`, `LEDG` (case-insensitive) */
  position?: string;
  /** `user` (default): user teams. `all`: every FBS team, on paid plans (403 `plan_required` otherwise) */
  scope?: ListRostersScope;
}

/** Query parameters for {@link DynastyAPI.listRosterSkills}. */
export interface ListRosterSkillsQuery {
  /** Season. Default: the newest cached season */
  season?: number;
  /** Team key */
  team?: number;
  /** Player key */
  player?: number;
}

/** Query parameters for {@link DynastyAPI.listCareers}. */
export interface ListCareersQuery {
  /** The read covering seasons through this one (`career_year`). Default: each rostered player's latest */
  year?: number;
  /** Team key (his team when read). A CPU team's players need a paid plan (without one, only user teams match) */
  team?: number;
  /** Player key. A CPU team's player needs a paid plan (without one, only user teams match) */
  player?: number;
  /** Position, e.g. `QB`, `LEDG` (case-insensitive) */
  position?: string;
  /** `user` (default): user teams. `all`: every FBS team, on paid plans (403 `plan_required` otherwise) */
  scope?: ListCareersScope;
}

/** Query parameters for {@link DynastyAPI.listSchoolGrades}. */
export interface ListSchoolGradesQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
  /** One grade, e.g. `Brand Exposure` */
  grade?: string;
  /** Only this team's rows, by team key (`team_key` in /standings) */
  team?: number;
}

/** Query parameters for {@link DynastyAPI.listPlayingStyleGrades}. */
export interface ListPlayingStyleGradesQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
  /** Only the ranking for this archetype, e.g. `WR - Speedster` */
  archetype?: string;
  /** Only this team's rows, by team key (`team_key` in /standings) */
  team?: number;
}

/** Query parameters for {@link DynastyAPI.listProPotentialGrades}. */
export interface ListProPotentialGradesQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
  /** `QB`, `RB`, `WR`, `TE`, `OL`, `DL`, `LB`, `DB`, `K`, `P` or `LS` */
  position_group?: string;
  /** Only this team's rows, by team key (`team_key` in /standings) */
  team?: number;
}

/** Query parameters for {@link DynastyAPI.listHeismanWatch}. */
export interface ListHeismanWatchQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
}

/** Query parameters for {@link DynastyAPI.listAwardWatches}. */
export interface ListAwardWatchesQuery {
  /** Period id, or `current`. Default: the newest period with data for this endpoint. */
  period?: string;
  /** `watch` (default) or `winners` */
  tab?: string;
  /** One award, e.g. `Maxwell Award` */
  award?: string;
}

/** Query parameters for {@link DynastyAPI.listAllAmericans}. */
export interface ListAllAmericansQuery {
  /** Season. Default: newest with awards */
  season?: number;
  /** `National` for All-American teams, or a conference name, e.g. `SEC` */
  conference?: string;
}

/** Query parameters for {@link DynastyAPI.listLeagueHistory}. */
export interface ListLeagueHistoryQuery {
  /** One season */
  season?: number;
  /** Seasons from this one on, e.g. the dynasty's first season to leave out real history */
  since?: number;
  /** Row kind */
  kind?: ListLeagueHistoryKind;
  /** A filter label (case-insensitive): `National Championships`, `Conference Championships` or an award, e.g. `Heisman Trophy` */
  title?: string;
  /** Rows for this team key: an award winner's team or either side of a championship */
  team?: number;
}

/** Endpoint methods for the Dynasty API (/v1). */
export abstract class DynastyAPI extends Transport {
  /**
   * League summary, sync status, current period and cached seasons
   *
   * `GET /v1/league`
   */
  getLeague(options?: RequestOptions): Promise<LeagueResponse> {
    return this.request<LeagueResponse>("GET", "/league", { ...options });
  }

  /**
   * Periods (in-game weeks/stages) seen, newest first
   *
   * `GET /v1/periods`
   */
  listPeriods(options?: RequestOptions): Promise<PeriodsResponse> {
    return this.request<PeriodsResponse>("GET", "/periods", { ...options });
  }

  /**
   * Seasons with cached games, newest first
   *
   * `GET /v1/seasons`
   */
  listSeasons(options?: RequestOptions): Promise<SeasonsResponse> {
    return this.request<SeasonsResponse>("GET", "/seasons", { ...options });
  }

  /**
   * A season's games
   *
   * `GET /v1/schedule`
   */
  listSchedule(query?: ListScheduleQuery, options?: RequestOptions): Promise<ScheduleResponse> {
    return this.request<ScheduleResponse>("GET", "/schedule", { query, ...options });
  }

  /**
   * One game, with its box score when cached. CPU-vs-CPU games' box scores are read and served on League Pro
   *
   * `GET /v1/games/{key}`
   */
  getGame(key: number, query?: GetGameQuery, options?: RequestOptions): Promise<GameResponse> {
    return this.request<GameResponse>("GET", `/games/${encodeURIComponent(String(key))}`, { query, ...options });
  }

  /**
   * A team's season from its side: location, opponent, outcome, scores, margin, matchup type, opponent's rank at game time
   *
   * `GET /v1/teams/{key}/schedule`
   */
  getTeamSchedule(key: number, query?: GetTeamScheduleQuery, options?: RequestOptions): Promise<TeamScheduleResponse> {
    return this.request<TeamScheduleResponse>("GET", `/teams/${encodeURIComponent(String(key))}/schedule`, { query, ...options });
  }

  /**
   * Every team's record, ratings, conference and poll rank
   *
   * `GET /v1/standings`
   */
  listStandings(query?: ListStandingsQuery, options?: RequestOptions): Promise<StandingsResponse> {
    return this.request<StandingsResponse>("GET", "/standings", { query, ...options });
  }

  /**
   * Every team's cumulative season stats and NIL spend by position (weekly)
   *
   * `GET /v1/team-stats`
   */
  listTeamStats(query?: ListTeamStatsQuery, options?: RequestOptions): Promise<TeamStatsResponse> {
    return this.request<TeamStatsResponse>("GET", "/team-stats", { query, ...options });
  }

  /**
   * League members: ready to advance, autopilot, this week's result, recruiting hours
   *
   * `GET /v1/members`
   */
  listMembers(query?: ListMembersQuery, options?: RequestOptions): Promise<MembersResponse> {
    return this.request<MembersResponse>("GET", "/members", { query, ...options });
  }

  /**
   * Cumulative season stats for players on user-controlled teams (weekly)
   *
   * `GET /v1/player-stats`
   */
  listPlayerStats(query?: ListPlayerStatsQuery, options?: RequestOptions): Promise<PlayerStatsResponse> {
    return this.request<PlayerStatsResponse>("GET", "/player-stats", { query, ...options });
  }

  /**
   * Weekly award winners (players of the week)
   *
   * `GET /v1/awards`
   */
  listAwards(query?: ListAwardsQuery, options?: RequestOptions): Promise<AwardsResponse> {
    return this.request<AwardsResponse>("GET", "/awards", { query, ...options });
  }

  /**
   * Every recruit in the national recruit search (weekly), in national rank order. Only what every league member sees in game: no scouted attributes, gem/bust or abilities, and dev trait only once a recruit has signed.
   *
   * `GET /v1/recruits`
   */
  listRecruits(query?: ListRecruitsQuery, options?: RequestOptions): Promise<RecruitsResponse> {
    return this.request<RecruitsResponse>("GET", "/recruits", { query, ...options });
  }

  /**
   * Commitment changes seen between weekly syncs, newest first: `commit` (with `previous_school` when it was a flip), `decommit`, `sign`. Changes before the league's first recruit sync aren't known; /recruits shows the current commitments.
   *
   * `GET /v1/recruits/commits`
   */
  listRecruitCommits(query?: ListRecruitCommitsQuery, options?: RequestOptions): Promise<RecruitCommitsResponse> {
    return this.request<RecruitCommitsResponse>("GET", "/recruits/commits", { query, ...options });
  }

  /**
   * The recruiting Top Classes list: every team's class by national rank, with conference rank, class points, commits by star rating and NIL committed (weekly). `overall` counts recruits and transfers together.
   *
   * `GET /v1/recruits/classes`
   */
  listRecruitingClasses(query?: ListRecruitingClassesQuery, options?: RequestOptions): Promise<RecruitingClassesResponse> {
    return this.request<RecruitingClassesResponse>("GET", "/recruits/classes", { query, ...options });
  }

  /**
   * Rosters, read once a period (each in-game week or stage; a team without one is read on the next sync): ratings, archetype, class, redshirt, dev trait, abilities, skill groups and unspent skill points. User teams by default; on paid plans CPU teams are read too and served with `scope=all` or `team`. `player_key` matches /player-stats.
   *
   * `GET /v1/rosters`
   */
  listRosters(query?: ListRostersQuery, options?: RequestOptions): Promise<RostersResponse> {
    return this.request<RostersResponse>("GET", "/rosters", { query, ...options });
  }

  /**
   * User team players' skill history over a season: each period's skill groups and unspent skill points, with the levels gained and points change since the period before. The game keeps no count of bought tiers; levels gained between periods are the purchases.
   *
   * `GET /v1/rosters/skills`
   */
  listRosterSkills(query?: ListRosterSkillsQuery, options?: RequestOptions): Promise<RosterSkillsResponse> {
    return this.request<RosterSkillsResponse>("GET", "/rosters/skills", { query, ...options });
  }

  /**
   * Player careers: each rostered player's season-by-season stats from the in-game player card, read once per completed season (the card only adds a season once it's over; offseason reads catch seniors and draft picks before they leave). By default each player on the newest roster with his latest read; `year` returns one read, players who have since left included. User teams by default; on paid plans CPU teams too with `scope=all` or `team`. `player_key` and `team_key` match /rosters and /player-stats; `stats` uses /player-stats' names (the card has the counting stats and basic rates, not the advanced ones).
   *
   * `GET /v1/careers`
   */
  listCareers(query?: ListCareersQuery, options?: RequestOptions): Promise<CareersResponse> {
    return this.request<CareersResponse>("GET", "/careers", { query, ...options });
  }

  /**
   * Recent sync runs
   *
   * `GET /v1/sync`
   */
  listSyncRuns(options?: RequestOptions): Promise<SyncRunsResponse> {
    return this.request<SyncRunsResponse>("GET", "/sync", { ...options });
  }

  /**
   * Every school's My School (recruiting pitch) grades, ranked: Academic Prestige, Athletic Facilities, Brand Exposure, Campus Lifestyle, Championship Contender, Coach Prestige, Coach Stability, Program Tradition and Stadium Atmosphere, plus Conference Prestige (conferences, not schools). The game shows only about a dozen schools around yours; this is the whole country. Read weekly, the sync after the weekly pull.
   *
   * `GET /v1/school-grades`
   */
  listSchoolGrades(query?: ListSchoolGradesQuery, options?: RequestOptions): Promise<SchoolGradesResponse> {
    return this.request<SchoolGradesResponse>("GET", "/school-grades", { query, ...options });
  }

  /**
   * Playing Style rankings. Each ranks every school by one stat over one set of players (every WR archetype ranks WR receptions; Pass Protector linemen rank team passing yards), so archetypes that share a ranking are grouped. `stat_value` is each school's value of that stat. KR, PR, LS and gadget archetypes have no Playing Style stat and are left out.
   *
   * `GET /v1/school-grades/playing-style`
   */
  listPlayingStyleGrades(query?: ListPlayingStyleGradesQuery, options?: RequestOptions): Promise<PlayingStyleGradesResponse> {
    return this.request<PlayingStyleGradesResponse>("GET", "/school-grades/playing-style", { query, ...options });
  }

  /**
   * Pro Potential rankings by position group, with each school's draft picks at the group over the last four years. It changes once a year and is read once a season.
   *
   * `GET /v1/school-grades/pro-potential`
   */
  listProPotentialGrades(query?: ListProPotentialGradesQuery, options?: RequestOptions): Promise<ProPotentialGradesResponse> {
    return this.request<ProPotentialGradesResponse>("GET", "/school-grades/pro-potential", { query, ...options });
  }

  /**
   * The Heisman Watch (top 4) as of the period, from the League Awards screen. Read weekly; in the preseason it ranks players before any game.
   *
   * `GET /v1/awards/heisman`
   */
  listHeismanWatch(query?: ListHeismanWatchQuery, options?: RequestOptions): Promise<HeismanWatchResponse> {
    return this.request<HeismanWatchResponse>("GET", "/awards/heisman", { query, ...options });
  }

  /**
   * Each annual award's ranked candidates (Awards Watch tab), or the Awards Winners tab, which shows the same candidates until the award is given. Read weekly. Awards without a watchlist yet (position awards until later in the season) are left out.
   *
   * `GET /v1/awards/watch`
   */
  listAwardWatches(query?: ListAwardWatchesQuery, options?: RequestOptions): Promise<AwardWatchesResponse> {
    return this.request<AwardWatchesResponse>("GET", "/awards/watch", { query, ...options });
  }

  /**
   * A season's All-American (`National`) and all-conference teams: the preseason 1st and 2nd teams, then the final 1st, 2nd and Freshman teams once awarded.
   *
   * `GET /v1/awards/all-american`
   */
  listAllAmericans(query?: ListAllAmericansQuery, options?: RequestOptions): Promise<AllAmericansResponse> {
    return this.request<AllAmericansResponse>("GET", "/awards/all-american", { query, ...options });
  }

  /**
   * League History (CFB History): national and conference championship games and every annual award's winner, all years, newest season first. Seasons before the dynasty began are the game's real history: no records, ranks, users or opponents. Read on each weekly sync.
   *
   * `GET /v1/history`
   */
  listLeagueHistory(query?: ListLeagueHistoryQuery, options?: RequestOptions): Promise<LeagueHistoryResponse> {
    return this.request<LeagueHistoryResponse>("GET", "/history", { query, ...options });
  }
}
